#[path="../../../🧳️native/🌱️construction/🧪️tests/🧰️leaf/🦀️.rs"]mod leaf_laws;
use crate::snapshot::original::EnergyModelSnapshot;
#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]enum Operation{Bind(crate::BindFenestrationGlazingConstruction),Clear(crate::ClearFenestrationGlazingConstruction)}
impl From<crate::BindFenestrationGlazingConstruction> for Operation{fn from(p:crate::BindFenestrationGlazingConstruction)->Self{Self::Bind(p)}}impl From<crate::ClearFenestrationGlazingConstruction> for Operation{fn from(p:crate::ClearFenestrationGlazingConstruction)->Self{Self::Clear(p)}}
impl protocol::Mutation<EnergyModelSnapshot> for Operation{type Diff=crate::diff::original::EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[<crate::BindFenestrationGlazingConstruction as protocol::MutationLeaf>::DESCRIPTOR,<crate::ClearFenestrationGlazingConstruction as protocol::MutationLeaf>::DESCRIPTOR];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{match self{Self::Bind(_)=>&<crate::BindFenestrationGlazingConstruction as protocol::MutationLeaf>::DESCRIPTOR,Self::Clear(_)=>&<crate::ClearFenestrationGlazingConstruction as protocol::MutationLeaf>::DESCRIPTOR}}}
#[test]fn original_glazing_facet_preserves_actual_optional_value_and_clear_absence_semantics(){for fixture in[include_str!("🧫️fixtures/🔣️.json"),include_str!("🧫️fixtures/∅️empty.json")]{core_laws::run::<__BindFenestrationGlazingConstructionNativeFacetPath>(fixture);}}
#[test]fn original_glazing_leaf_issues_exact_bind_or_clear_inverse_and_empty_noop_inverse(){for(present,fixture)in[(true,include_str!("🧫️fixtures/🔣️.json")),(false,include_str!("🧫️fixtures/∅️empty.json"))]{if present{leaf_laws::run::<BindFenestrationGlazingConstruction,Operation>(fixture,ids,|op|match op{Operation::Bind(p)=>{assert_eq!(p.construction_id.0,1);p.id.0},_=>panic!("original bound construction must restore its actual bind intent")});}else{leaf_laws::run::<BindFenestrationGlazingConstruction,Operation>(fixture,ids,|op|match op{Operation::Clear(p)=>p.id.0,_=>panic!("original empty construction must restore its actual clear intent")});}}}
fn ids(post:&EnergyModelSnapshot)->Vec<u32>{let rows=&post.model.geometry.get().fenestrations;(0..rows.len()).map(|i|rows.get(i).unwrap().id.0).collect()}
